import{S as t}from"./chunks/theme.CMKb-o9K.js";import{o as i,c as s,j as a,a as n,G as r,a2 as o}from"./chunks/framework.BgSoyxN5.js";const p=JSON.parse('{"title":"Fundamental Stock Screener: Quality, Valuation, and Financial Strength Filters","description":"Learn which fundamental stock screener filters matter for investors: revenue growth, margins, free cash flow, debt, valuation, Piotroski score, business quality, Smart Money, and insider context.","frontmatter":{"title":"Fundamental Stock Screener: Quality, Valuation, and Financial Strength Filters","description":"Learn which fundamental stock screener filters matter for investors: revenue growth, margins, free cash flow, debt, valuation, Piotroski score, business quality, Smart Money, and insider context.","date":"2026-06-28T00:00:00.000Z","keywords":["fundamental stock screener","best free fundamental stock screener","best fundamental stock screener","best growth stock screener","best stock screener for fundamental analysis","best value stock screener","dcf stock screener","deep value stock screener","enterprise value stock screener","fair value stock screener","free cash flow screener","free cash flow yield screener","free cash flow yield stock screener"],"canonical":"https://ticker-forge.com/blog/fundamental-stock-screener"},"headers":[],"relativePath":"blog/fundamental-stock-screener.md","filePath":"blog/fundamental-stock-screener.md","lastUpdated":1785044000000}'),l={name:"blog/fundamental-stock-screener.md"},g=Object.assign(l,{setup(c){return(h,e)=>(i(),s("div",null,[e[0]||(e[0]=a("h1",{id:"fundamental-stock-screener-quality-valuation-and-financial-strength-filters",tabindex:"-1"},[n("Fundamental Stock Screener: Quality, Valuation, and Financial Strength Filters "),a("a",{class:"header-anchor",href:"#fundamental-stock-screener-quality-valuation-and-financial-strength-filters","aria-label":'Permalink to "Fundamental Stock Screener: Quality, Valuation, and Financial Strength Filters"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Most investors start stock research with a chart, a headline, or a ticker they saw on social media. A fundamental stock screener starts somewhere more useful: the business itself.",-1)),e[2]||(e[2]=a("p",null,"Before price action, technical indicators, or momentum matter, the company needs to pass a basic test:",-1)),e[3]||(e[3]=a("p",null,[a("strong",null,"Is this a business worth researching further?")],-1)),e[4]||(e[4]=a("p",null,"A good fundamental stock screener should not simply return a list of cheap-looking tickers. It should help investors remove fragile companies, spot higher-quality businesses, and decide which stocks deserve deeper research. The best stock screener for fundamental analysis combines quality, financial strength, valuation, and context — not one ratio in isolation.",-1)),e[5]||(e[5]=a("p",null,"TickerForge goes one step further. Instead of stopping at raw filters like revenue growth, EBITDA, P/E, or free cash flow yield, TickerForge connects those metrics to a broader decision snapshot: business quality, valuation, risk, technical setup, Smart Money activity, insider activity, and a final action label.",-1)),e[6]||(e[6]=a("p",null,"That is the difference between a filter table and a decision engine.",-1)),r(t,{title:"Move from fundamental filters to a live screener",description:"Use the Smart Money & Insider Radar to find companies where ownership activity, business quality, technical setup, and TickerForge action labels point to a stronger research candidate."}),e[7]||(e[7]=o(`<hr><h2 id="what-a-fundamental-stock-screener-should-check" tabindex="-1">What a Fundamental Stock Screener Should Check <a class="header-anchor" href="#what-a-fundamental-stock-screener-should-check" aria-label="Permalink to &quot;What a Fundamental Stock Screener Should Check&quot;">​</a></h2><p>A fundamental stock screener filters companies based on the business itself: revenue, margins, cash generation, debt, balance-sheet strength, valuation, and financial resilience.</p><p>The goal is not to predict the next daily move. The goal is to reduce a large market universe into a smaller research list.</p><p>A useful fundamental screener should answer four questions:</p><ol><li><strong>Quality:</strong> Is the company operationally strong?</li><li><strong>Financial strength:</strong> Can the balance sheet survive stress?</li><li><strong>Valuation:</strong> Is the price reasonable for the quality of the business?</li><li><strong>Decision context:</strong> Does the stock also have acceptable timing, risk, Smart Money support, or insider confirmation?</li></ol><p>Most basic screeners only answer the first three partially. They let users stack filters such as revenue growth above 10%, EBITDA margin above 15%, or P/E below 20. That is useful, but incomplete.</p><p>A stock can pass those filters and still be a weak idea if:</p><ul><li>cash flow is deteriorating;</li><li>debt is rising too fast;</li><li>the market regime is hostile;</li><li>technical setup is broken;</li><li>funds are reducing exposure;</li><li>insider selling pressure is elevated;</li><li>the stock would increase portfolio concentration.</li></ul><p>That is why fundamental screening should be treated as the first layer of research, not the final verdict.</p><hr><h2 id="quality-filters-growth-margins-and-free-cash-flow" tabindex="-1">Quality Filters: Growth, Margins, and Free Cash Flow <a class="header-anchor" href="#quality-filters-growth-margins-and-free-cash-flow" aria-label="Permalink to &quot;Quality Filters: Growth, Margins, and Free Cash Flow&quot;">​</a></h2><p>Quality filters answer one question:</p><p><strong>Is this business actually getting better, or just getting bigger?</strong></p><p>Revenue growth is the most common filter, but raw growth is a weak signal by itself. A company can grow revenue quickly while losing money on every additional dollar of sales. That is not business quality. That is expensive growth.</p><p>A better quality screen combines several signals.</p><h3 id="revenue-growth" tabindex="-1">Revenue growth <a class="header-anchor" href="#revenue-growth" aria-label="Permalink to &quot;Revenue growth&quot;">​</a></h3><p>Revenue growth shows whether demand is expanding. But the trend matters more than a single year. Consistent growth across several periods usually tells more than one exceptional quarter.</p><p>Useful checks:</p><ul><li>revenue growth over one year;</li><li>revenue growth over several years;</li><li>revenue growth compared with sector peers;</li><li>revenue growth alongside margin trend.</li></ul><h3 id="margin-trend" tabindex="-1">Margin trend <a class="header-anchor" href="#margin-trend" aria-label="Permalink to &quot;Margin trend&quot;">​</a></h3><p>Margins show whether growth is becoming more efficient.</p><p>If revenue rises while operating margin expands, the company may be showing operating leverage. If revenue rises while margins compress, the company may be buying growth through discounts, marketing spend, or higher operating costs.</p><p>Important margin filters:</p><ul><li>gross margin;</li><li>operating margin;</li><li>net margin;</li><li>margin trend over time.</li></ul><h3 id="free-cash-flow" tabindex="-1">Free cash flow <a class="header-anchor" href="#free-cash-flow" aria-label="Permalink to &quot;Free cash flow&quot;">​</a></h3><p>Free cash flow is one of the strongest quality filters because it shows whether the business produces cash after capital expenditures.</p><p>A free cash flow screener helps separate companies that only look profitable from companies that can actually fund growth, reduce debt, buy back shares, or survive downturns.</p><p>A useful formula:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Free Cash Flow = Operating Cash Flow − Capital Expenditures</span></span></code></pre></div><p>A free cash flow yield stock screener adds valuation context:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Free Cash Flow Yield = Free Cash Flow / Enterprise Value</span></span></code></pre></div><p>High free cash flow yield can be attractive, but only if the business is not structurally deteriorating. A high yield from a declining company can be a value trap.</p><hr><h2 id="financial-strength-filters-debt-liquidity-and-distress-risk" tabindex="-1">Financial Strength Filters: Debt, Liquidity, and Distress Risk <a class="header-anchor" href="#financial-strength-filters-debt-liquidity-and-distress-risk" aria-label="Permalink to &quot;Financial Strength Filters: Debt, Liquidity, and Distress Risk&quot;">​</a></h2><p>A profitable business can still become a bad investment if the balance sheet is weak.</p><p>Financial strength filters answer a different question from quality filters:</p><p><strong>Can this company survive a bad year?</strong></p><p>The strongest fundamental screeners check debt, liquidity, and distress risk before valuation.</p><h3 id="debt-and-leverage" tabindex="-1">Debt and leverage <a class="header-anchor" href="#debt-and-leverage" aria-label="Permalink to &quot;Debt and leverage&quot;">​</a></h3><p>Debt is not automatically bad. Many stable businesses use debt responsibly. The risk appears when debt grows faster than the company’s ability to service it.</p><p>Useful checks:</p><ul><li>Debt to Equity;</li><li>Net Debt to EBITDA;</li><li>interest coverage;</li><li>debt maturity schedule;</li><li>cash compared with short-term obligations.</li></ul><p>A Debt to Equity ratio above 2.0 is not always fatal, but it usually deserves extra caution, especially outside sectors where leverage is structurally normal.</p><h3 id="liquidity" tabindex="-1">Liquidity <a class="header-anchor" href="#liquidity" aria-label="Permalink to &quot;Liquidity&quot;">​</a></h3><p>Liquidity filters show whether the company can handle near-term obligations.</p><p>Common checks:</p><ul><li>current ratio;</li><li>quick ratio;</li><li>cash and equivalents;</li><li>short-term debt;</li><li>working-capital trend.</li></ul><p>A company can report positive net income and still face pressure if cash is low and short-term liabilities are high.</p><h3 id="piotroski-f-score" tabindex="-1">Piotroski F-Score <a class="header-anchor" href="#piotroski-f-score" aria-label="Permalink to &quot;Piotroski F-Score&quot;">​</a></h3><p>The Piotroski F-Score is a composite financial strength score from 0 to 9. It checks profitability, leverage, liquidity, and operating efficiency.</p><p>A high Piotroski score does not guarantee strong stock performance, but it helps identify companies where several fundamental conditions are improving at the same time.</p><p>That matters because a single ratio can be misleading. A composite score is harder to fake.</p><h3 id="altman-z-score" tabindex="-1">Altman Z-Score <a class="header-anchor" href="#altman-z-score" aria-label="Permalink to &quot;Altman Z-Score&quot;">​</a></h3><p>Altman Z-Score estimates financial distress risk using profitability, leverage, liquidity, and balance-sheet variables.</p><p>This is especially useful for value and deep value screens. Many statistically cheap stocks are cheap because the market is pricing in real bankruptcy or dilution risk.</p><p>A fundamental screener should not treat a low valuation as attractive until financial strength has been checked.</p><hr><h2 id="valuation-filters-dcf-multiples-and-fair-value" tabindex="-1">Valuation Filters: DCF, Multiples, and Fair Value <a class="header-anchor" href="#valuation-filters-dcf-multiples-and-fair-value" aria-label="Permalink to &quot;Valuation Filters: DCF, Multiples, and Fair Value&quot;">​</a></h2><p>Valuation should be the final fundamental layer, not the first.</p><p>A low multiple means little if the business is weak. A high multiple may be justified if business quality, growth durability, and cash generation are strong.</p><h3 id="multiples" tabindex="-1">Multiples <a class="header-anchor" href="#multiples" aria-label="Permalink to &quot;Multiples&quot;">​</a></h3><p>Common valuation filters include:</p><ul><li>P/E;</li><li>P/B;</li><li>EV/EBITDA;</li><li>EV/Sales;</li><li>P/FCF;</li><li>EV/FCF.</li></ul><p>Multiples are useful for quick comparison, especially inside the same sector. But they are dangerous when used across different business models.</p><p>A low P/E can mean undervaluation. It can also mean the market expects earnings to fall.</p><h3 id="enterprise-value" tabindex="-1">Enterprise value <a class="header-anchor" href="#enterprise-value" aria-label="Permalink to &quot;Enterprise value&quot;">​</a></h3><p>Enterprise value matters because it includes debt and cash.</p><p>Two companies can have the same market capitalization but very different enterprise values. If one company carries heavy debt and the other has net cash, they are not equally valued.</p><p>That is why an enterprise value stock screener can be more useful than a simple market-cap or P/E filter.</p><h3 id="dcf-and-fair-value" tabindex="-1">DCF and fair value <a class="header-anchor" href="#dcf-and-fair-value" aria-label="Permalink to &quot;DCF and fair value&quot;">​</a></h3><p>A DCF stock screener estimates intrinsic value using projected future cash flows discounted to the present.</p><p>This is more rigorous than a simple multiple, but also more sensitive. Small changes in growth assumptions, terminal value, or discount rate can meaningfully change the result.</p><p>A fair value stock screener is most useful when the fair value gap is interpreted alongside business quality and financial strength.</p><p>The strongest setup is not simply “cheap.” It is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Good or strong business quality</span></span>
<span class="line"><span>+ acceptable risk</span></span>
<span class="line"><span>+ reasonable or attractive valuation</span></span>
<span class="line"><span>+ constructive timing</span></span></code></pre></div><hr><h2 id="why-raw-fundamental-filters-are-not-enough" tabindex="-1">Why Raw Fundamental Filters Are Not Enough <a class="header-anchor" href="#why-raw-fundamental-filters-are-not-enough" aria-label="Permalink to &quot;Why Raw Fundamental Filters Are Not Enough&quot;">​</a></h2><p>Traditional screeners are useful, but they often stop too early.</p><p>They answer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which stocks match my filters?</span></span></code></pre></div><p>A better research workflow asks:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which stocks deserve attention, what is the risk, and what should I do next?</span></span></code></pre></div><p>Raw filters can create false confidence. For example:</p><ul><li>revenue growth can hide margin compression;</li><li>low P/E can hide falling earnings quality;</li><li>high dividend yield can hide payout risk;</li><li>low debt can still exist inside a weak business model;</li><li>high free cash flow yield can reflect a shrinking business;</li><li>a strong fundamental score can still have terrible timing.</li></ul><p>That is why a modern stock screener should combine fundamentals with decision context.</p><hr><h2 id="how-to-use-this-screener-in-stock-analysis" tabindex="-1">How to Use This Screener in Stock Analysis <a class="header-anchor" href="#how-to-use-this-screener-in-stock-analysis" aria-label="Permalink to &quot;How to Use This Screener in Stock Analysis&quot;">​</a></h2><p>Use a fundamental screen to build the first research queue, not to make the final decision. Start from the <a href="/stock-screener">TickerForge Stock Screener</a>, filter for quality, cash flow, valuation, and financial strength, then open the most interesting names in the <a href="/stock-widget">Stock Widget</a>.</p><p>That second step matters because a company can pass fundamental filters while still having weak timing, deteriorating risk, heavy insider selling, or poor portfolio fit. TickerForge is designed to turn the screen into a structured check: business first, then valuation, risk, ownership context, timing, and only then monitoring or portfolio review.</p><hr><h2 id="how-tickerforge-turns-fundamentals-into-a-decision-snapshot" tabindex="-1">How TickerForge Turns Fundamentals Into a Decision Snapshot <a class="header-anchor" href="#how-tickerforge-turns-fundamentals-into-a-decision-snapshot" aria-label="Permalink to &quot;How TickerForge Turns Fundamentals Into a Decision Snapshot&quot;">​</a></h2><p>TickerForge uses a structured <strong>Company Decision Snapshot</strong> to move beyond raw financial filters.</p><p>Instead of showing only isolated metrics, TickerForge evaluates a company across multiple decision dimensions:</p><ul><li><strong>overall verdict;</strong></li><li><strong>action label;</strong></li><li><strong>business quality state;</strong></li><li><strong>valuation state;</strong></li><li><strong>technical setup state;</strong></li><li><strong>risk state;</strong></li><li><strong>overall score;</strong></li><li><strong>technical entry score;</strong></li><li><strong>Piotroski score;</strong></li><li><strong>Altman Z-Score;</strong></li><li><strong>DCF gap;</strong></li><li><strong>P/E, P/FCF, and P/B;</strong></li><li><strong>Debt to Equity and Current Ratio;</strong></li><li><strong>revenue, EPS, and free cash flow growth;</strong></li><li><strong>sector, industry, market cap, and liquidity context.</strong></li></ul><p>This makes the screener more useful because it does not force the investor to manually combine dozens of fields.</p><p>For example, a company may look attractive on valuation but still receive a weak action label if business quality is deteriorating, risk is elevated, or the technical setup is poor. Another company may not look deeply undervalued, but still deserve attention if business quality, financial strength, timing, and Smart Money context align.</p><p>The point is not to replace research. The point is to make the first pass faster and more consistent.</p><hr><h2 id="smart-money-and-insider-context-the-tickerforge-smart-radar-advantage" tabindex="-1">Smart Money and Insider Context: The TickerForge Smart Radar Advantage <a class="header-anchor" href="#smart-money-and-insider-context-the-tickerforge-smart-radar-advantage" aria-label="Permalink to &quot;Smart Money and Insider Context: The TickerForge Smart Radar Advantage&quot;">​</a></h2><p>TickerForge also connects fundamental screening with <strong>Smart Money</strong> and <strong>insider activity</strong>.</p><p>That matters because fundamentals tell you what the business looks like, while ownership and insider data can add another layer of evidence.</p><p>The <a href="/smart-money-radar">Smart Money &amp; Insider Radar</a> is designed to find companies where several signals align:</p><ul><li>fund ownership changes;</li><li>13F accumulation or institutional run behavior;</li><li>business quality;</li><li>technical setup;</li><li>reported insider buying or selling;</li><li>final TickerForge action label.</li></ul><p>This is different from a basic screener that only says:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue growth &gt; 10%</span></span>
<span class="line"><span>EBITDA margin &gt; 15%</span></span>
<span class="line"><span>P/E &lt; 20</span></span></code></pre></div><p>Those filters may find a list of companies. TickerForge Smart Radar tries to answer a more useful question:</p><p><strong>Where do fundamentals, institutional activity, insider context, and the current decision snapshot point in the same direction?</strong></p><p>Examples of advanced Smart Money screens include:</p><ul><li><strong>Positive 13F Flow:</strong> companies with favorable institutional flow regimes.</li><li><strong>Clean Accumulation:</strong> positive fund flow with stronger sponsorship quality.</li><li><strong>Insider Confirmed:</strong> positive fund flow plus recent positive insider activity.</li><li><strong>Insider + Quality:</strong> insider confirmation combined with acceptable or better business quality.</li><li><strong>Buyable / Accumulate:</strong> positive fund flow plus favorable TickerForge action labels.</li><li><strong>Constructive Setup:</strong> positive fund flow plus constructive technical structure.</li><li><strong>High Conviction:</strong> stricter alignment across sponsorship, business quality, and setup.</li><li><strong>Quiet Accumulation:</strong> fund accumulation before the price has fully confirmed.</li><li><strong>Institutional Run:</strong> stocks where ownership and price strength are already moving together.</li><li><strong>Capital Quality:</strong> accumulation involving high-quality institutional sponsors.</li><li><strong>Divergence:</strong> cases where tracked funds increase exposure while price is still flat or weak.</li></ul><p>None of these labels is an automatic buy signal. They are discovery filters. Their job is to reduce noise and help investors find better candidates for deeper research.</p><hr><h2 id="common-fundamental-screener-mistakes" tabindex="-1">Common Fundamental Screener Mistakes <a class="header-anchor" href="#common-fundamental-screener-mistakes" aria-label="Permalink to &quot;Common Fundamental Screener Mistakes&quot;">​</a></h2><h3 id="screening-on-one-ratio" tabindex="-1">Screening on one ratio <a class="header-anchor" href="#screening-on-one-ratio" aria-label="Permalink to &quot;Screening on one ratio&quot;">​</a></h3><p>A single metric almost never tells the full story.</p><p>A low P/E stock may be cheap for a reason. A high free cash flow yield may reflect a shrinking business. Strong revenue growth may be supported by falling margins or rising debt.</p><p>Use ratios as evidence, not verdicts.</p><h3 id="treating-cheap-as-good" tabindex="-1">Treating cheap as good <a class="header-anchor" href="#treating-cheap-as-good" aria-label="Permalink to &quot;Treating cheap as good&quot;">​</a></h3><p>A value stock screener can surface companies that are cheap because the market is wrong. It can also surface companies that are cheap because the business is deteriorating.</p><p>That is why valuation should come after quality and financial strength.</p><h3 id="ignoring-sector-differences" tabindex="-1">Ignoring sector differences <a class="header-anchor" href="#ignoring-sector-differences" aria-label="Permalink to &quot;Ignoring sector differences&quot;">​</a></h3><p>Debt levels, margins, and capital intensity vary by sector.</p><p>A debt ratio that looks dangerous in a software company may be normal in utilities, banks, or REITs. A low margin business may still be attractive if asset turnover and cash conversion are strong.</p><p>Screeners should help you compare companies inside the right context.</p><h3 id="ignoring-trend-direction" tabindex="-1">Ignoring trend direction <a class="header-anchor" href="#ignoring-trend-direction" aria-label="Permalink to &quot;Ignoring trend direction&quot;">​</a></h3><p>A snapshot metric is less useful than a trend.</p><p>Two companies can have the same operating margin today, but one may be improving while the other is deteriorating. The direction often matters as much as the level.</p><h3 id="ignoring-portfolio-fit" tabindex="-1">Ignoring portfolio fit <a class="header-anchor" href="#ignoring-portfolio-fit" aria-label="Permalink to &quot;Ignoring portfolio fit&quot;">​</a></h3><p>A stock can be fundamentally attractive and still be a poor portfolio addition.</p><p>If your portfolio is already concentrated in semiconductors, adding another high-beta AI infrastructure stock may increase hidden risk even if the company itself looks strong.</p><p>That is why a screener should eventually connect to portfolio diagnostics, not stop at the single-stock level.</p><hr><h2 id="how-to-use-tickerforge-after-a-fundamental-screen" tabindex="-1">How to Use TickerForge After a Fundamental Screen <a class="header-anchor" href="#how-to-use-tickerforge-after-a-fundamental-screen" aria-label="Permalink to &quot;How to Use TickerForge After a Fundamental Screen&quot;">​</a></h2><p>A practical workflow looks like this:</p><ol><li>Start with the <a href="/stock-screener">TickerForge Stock Screener</a>, <a href="/stockdiscovery">Free Stock Discovery</a>, or <a href="/smart-money-radar">Smart Money Radar</a>.</li><li>Use fundamental filters to find companies with acceptable business quality, valuation, and financial strength.</li><li>Open a candidate in the <a href="/stock-widget">Stock Analysis Widget</a>.</li><li>Check the Company Decision Snapshot: business quality, valuation, risk, technical setup, and action label.</li><li>Review Smart Money and insider context.</li><li>If the stock still looks interesting, test its impact on your portfolio with <a href="/portfolio-analysis">Portfolio Analysis</a>.</li></ol><p>This keeps the process structured:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Screen → Diagnose → Decide → Monitor</span></span></code></pre></div><p>That is the core TickerForge idea. The screener does not tell you what to buy. It helps you decide what is worth researching, what should be skipped, and what deserves an alert.</p><hr><h2 id="read-next" tabindex="-1">Read Next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read Next&quot;">​</a></h2><ul><li><p><a href="/stockdiscovery">Free Stock Discovery</a> - use the live free screener for business value, guarded fair value, cash flow, technical entry, and Workspace-unlocked Timing.</p></li><li><p><a href="/smart-money-radar">Smart Money &amp; Insider Radar</a> — use the live screener to combine institutional flow, insider context, business quality, and technical setup.</p></li><li><p><a href="/stock-screener">TickerForge Stock Screener</a> — the product hub for quality, risk, timing, Smart Money, insider activity, and portfolio fit.</p></li><li><p><a href="/blog/momentum-stock-screener">Momentum Stock Screener</a> — understand timing, trend, RSI, ADX, and entry setup filters.</p></li><li><p><a href="/methodology/tickerforge-score">TickerForge Score Methodology</a> — how business quality is evaluated.</p></li><li><p><a href="/methodology/dcf-model">DCF Model Methodology</a> — how fair value is estimated.</p></li><li><p><a href="/stock-widget">Analyze One Stock</a> — check a ticker through the TickerForge decision stack.</p></li><li><p><a href="/portfolio-analysis">Portfolio Analysis</a> — see whether a screened stock fits your existing portfolio.</p></li></ul><hr><p><em>Start with the business, not the hype. Use the <strong><a href="/smart-money-radar">Smart Money &amp; Insider Radar</a></strong> to move from fundamental screening to a shorter list of companies where ownership activity, business quality, setup, and action labels deserve a closer look.</em></p>`,143))]))}});export{p as __pageData,g as default};
